use seedbox_engine_core::{links, rng};
// Golden results generated by running this trace against origin/main at 7a42b56.
// These are semantic stream/witness values; no engine or artifact pins.

use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, BTreeSet};

fn trace(seed: u64) -> Value {
    let names = vec!["a".into(), "b".into(), "c".into()];
    let policy = links::Policy {
        latency_ns: 100,
        jitter_ns: 50,
        loss_ppm: 500_000,
        bandwidth_bps: None,
        queue_bound_ns: None,
    };
    let mut links = links::Links::new(seed, &names, policy, BTreeMap::new()).unwrap();
    let mut outcomes = Vec::new();
    for send in 0..128 {
        if send == 20 {
            links
                .shape(1, "shape".into(), BTreeSet::from([(0, 1)]), policy)
                .unwrap();
        }
        if send == 80 {
            links.heal("shape");
        }
        if send % 7 == 0 {
            links.selected_drop(0, 1);
        }
        outcomes.push(format!(
            "{:?}",
            links.decide(0, 1, send, 1500, send % 11 == 0)
        ));
        links.decide(1, 0, send, 1500, false);
    }
    let mut witness = Sha256::new();
    links.witness(&mut witness);
    let mut rng = rng::Rng::new(seed, "timer-jitter/a/0");
    let draws: Vec<_> = (0..16).map(|_| rng.next()).collect();
    json!({"seed":seed,"outcome_digest":hex::encode(Sha256::digest(serde_json::to_vec(&outcomes).unwrap())),"link_witness":hex::encode(witness.finalize()),
        "timer_draws":draws})
}

#[test]
fn no_checkpoint_streams_results_and_witnesses_equal_main() {
    let expected: Value =
        serde_json::from_str(include_str!("fixtures/checkpoint-feature-off-main.json")).unwrap();
    let observed = json!([0, 1, 2, 1009, u64::MAX].map(trace));
    assert_eq!(observed, expected);
}
